     <script>
       const notificationOptions = [
         { id: "notification-email", value: "email", label: "Email" },
         { id: "notification-sms", value: "sms", label: "SMS" },
         { id: "notification-push", value: "push", label: "Push Notifications" },
       ];

       function RadioOption({ id, value, label }) {
         return `
           <div class="radio-option">
             <input id="${id}" type="radio" name="notificationPreference" value="${value}" required>
             <label for="${id}">${label}</label>
           </div>
         `;
       }

       function NotificationForm() {
         return `
           <form id="notification-form">
             <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required field</p>
             <div class="form-field">
               <fieldset aria-describedby="notification-help">
                 <legend>
                   How do you prefer to receive notifications?
                   <span class="required-marker" aria-hidden="true">*</span>
                 </legend>
                 <p id="notification-help" class="field-help">Choose one notification method.</p>
                 <div class="radio-list">
                   ${notificationOptions.map(RadioOption).join("")}
                 </div>
               </fieldset>
             </div>
             <button type="submit">Save notification preference</button>
             <p id="form-status" class="status" role="status" aria-live="polite"></p>
           </form>
         `;
       }

       function App() {
         return `
           <main id="main-content" class="page-shell">
             <section class="card" aria-labelledby="page-title">
               <p class="eyebrow">Account settings</p>
               <h1 id="page-title">Notification preferences</h1>
               <p class="intro">
                 Pick the channel that best fits how you want to stay updated.
               </p>
               ${NotificationForm()}
             </section>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = App();

       document.getElementById("notification-form").addEventListener("submit", (event) => {
         event.preventDefault();

         if (!event.currentTarget.reportValidity()) {
           return;
         }

         const selected = event.currentTarget.elements.notificationPreference.value;
         const option = notificationOptions.find((item) => item.value === selected);
         document.getElementById("form-status").textContent =
           `Preference saved: ${option.label}.`;
       });
     </script>
   </body>
 </html>

